import React, { useRef, useState } from 'react';
import useInView from '../hooks/useInView';
import './Collections.css';

const products = [
  { id: 1, name: 'Ethiopian Cross Ring', category: 'Rings', price: '$145', image: null },
  { id: 2, name: 'Habesha Pendant', category: 'Necklaces', price: '$220', image: null },
  { id: 3, name: 'Gold Link Bracelet', category: 'Bracelets', price: '$98', image: null },
  { id: 4, name: 'Filigree Earrings', category: 'Earrings', price: '$115', image: null },
  { id: 5, name: 'Tsinat Choker', category: 'Necklaces', price: '$185', image: null },
  { id: 6, name: 'Melkam Cuff', category: 'Bracelets', price: '$130', image: null },
];

export default function Collections() {
  const [headerRef, headerVisible] = useInView(0.1);
  const scrollRef = useRef(null);

  const scroll = (dir) => {
    scrollRef.current.scrollBy({ left: dir * 320, behavior: 'smooth' });
  };

  return (
    <section className="collections" id="collections">
      <div className="collections-header" ref={headerRef}>
        <div className={`fade-up ${headerVisible ? 'visible' : ''}`}>
          <div className="section-label">Curated For You</div>
          <h2 className="collections-title">Our <em>Collections</em></h2>
        </div>
      </div>

      {/* Scrollable card row */}
      <div className="scroll-row-wrap">
        <div className="scroll-row" ref={scrollRef}>
          {products.map((product, i) => (
            <ScrollCard key={product.id} product={product} index={i} />
          ))}
        </div>

        {/* Arrow buttons */}
        <button className="scroll-btn left" onClick={() => scroll(-1)} aria-label="Scroll left">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
            <path d="M19 12H5M12 5l-7 7 7 7"/>
          </svg>
        </button>
        <button className="scroll-btn right" onClick={() => scroll(1)} aria-label="Scroll right">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
            <path d="M5 12h14M12 5l7 7-7 7"/>
          </svg>
        </button>
      </div>

      {/* View all button */}
      <div className="collections-footer">
        <a href="/shop" className="btn-view-all">
          <span>View All Pieces</span>
          <div className="btn-line" />
        </a>
      </div>
    </section>
  );
}

function ScrollCard({ product, index }) {
  const gradients = [
    'linear-gradient(145deg, #c8a040, #5C4209)',
    'linear-gradient(145deg, #e8c460, #8B6914)',
    'linear-gradient(145deg, #d4b060, #7a5c10)',
    'linear-gradient(145deg, #f0d080, #9a7020)',
    'linear-gradient(145deg, #b89040, #5C4209)',
    'linear-gradient(145deg, #e0c060, #8B6914)',
  ];

  return (
    <div className="scroll-card">
      <div className="scroll-card-img" style={{ background: product.image ? 'none' : gradients[index % gradients.length] }}>
        {product.image
          ? <img src={product.image} alt={product.name} />
          : <span className="scroll-card-placeholder">✦</span>
        }
        <div className="scroll-card-shop-btn">Shop</div>
      </div>
      <div className="scroll-card-info">
        <div className="scroll-card-name">{product.name}</div>
        <div className="scroll-card-price">{product.price}</div>
      </div>
    </div>
  );
}
